#!/usr/bin/env python3
"""
Visualize multi-camera pointcloud using step2a depth + step2b extrinsics.

Unprojacts stereo depth from all 3 cameras (wrist, ext1, ext2) into a combined
world-frame pointcloud and generates an interactive Three.js HTML viewer.

External camera extrinsics come from the step2b cameras JSON.
Wrist camera extrinsics come from DROID trajectory.h5 (time-varying gripper pose).

Usage:
    python scripts/visualize_pointcloud.py \
        --episode_dir /path/to/raw/episode \
        --depth_h5 output/step2a_depth/shard00000_ep000_depth.h5 \
        --cameras_json output/step2b_extrinsics/shard00000_ep000_cameras.json \
        --calibration_json output/svo_calibration.json \
        --frame_idx 80 \
        --output_html output/vis_pc.html
"""

import argparse
import json
import numpy as np
import cv2
import h5py
from pathlib import Path
from scipy.spatial.transform import Rotation

CAM_NAMES = ["wrist", "ext1", "ext2"]
CAMERA_COLORS = {"wrist": "#ff4444", "ext1": "#44cc44", "ext2": "#4488ff"}


# ---------------------------------------------------------------------------
# Data loading
# ---------------------------------------------------------------------------
def load_episode_metadata(episode_dir):
    meta_files = list(Path(episode_dir).glob("metadata_*.json"))
    if not meta_files:
        raise FileNotFoundError(f"No metadata JSON in {episode_dir}")
    with open(meta_files[0]) as f:
        return json.load(f)


def get_calibration(calibration_db, uuid, serial):
    entry = calibration_db[uuid][serial]
    cm = entry["cameraMatrix"]
    K = np.array([[cm[0], 0, cm[1]], [0, cm[2], cm[3]], [0, 0, 1]], dtype=np.float64)
    return K


def read_frame_from_mp4(mp4_path, frame_idx):
    """Read a single RGB frame from an MP4 (mono or stereo)."""
    cap = cv2.VideoCapture(str(mp4_path))
    if not cap.isOpened():
        return None
    w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
    is_stereo = w > 1920
    cap.set(cv2.CAP_PROP_POS_FRAMES, frame_idx)
    ret, frame = cap.read()
    cap.release()
    if not ret:
        return None
    rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
    if is_stereo:
        rgb = rgb[:, : w // 2]
    return rgb


def get_wrist_T_c2w(trajectory_path, wrist_serial, frame_idx):
    """Get wrist camera-to-world transform from DROID trajectory.h5.

    DROID stores camera extrinsics as [x, y, z, rx, ry, rz] where
    rotation is Euler XYZ angles describing the camera pose in the
    robot base (world) frame.
    """
    with h5py.File(str(trajectory_path), "r") as f:
        key = f"observation/camera_extrinsics/{wrist_serial}_left"
        ext_6dof = f[key][frame_idx]

    x, y, z, rx, ry, rz = ext_6dof
    R = Rotation.from_euler("xyz", [rx, ry, rz]).as_matrix()
    T_c2w = np.eye(4)
    T_c2w[:3, :3] = R
    T_c2w[:3, 3] = [x, y, z]
    return T_c2w


# ---------------------------------------------------------------------------
# Pointcloud generation
# ---------------------------------------------------------------------------
def unproject_depth(depth, K, rgb, max_depth=3.0, downsample=4):
    """Unproject depth map to 3D camera-frame points with RGB colors.

    Returns (points_cam (N,3), colors (N,3) uint8).
    """
    H, W = depth.shape
    u = np.arange(0, W, downsample)
    v = np.arange(0, H, downsample)
    uu, vv = np.meshgrid(u, v)
    dd = depth[::downsample, ::downsample]

    valid = (dd > 0.01) & (dd < max_depth) & np.isfinite(dd)

    uu_v = uu[valid].astype(np.float64)
    vv_v = vv[valid].astype(np.float64)
    dd_v = dd[valid].astype(np.float64)

    fx, fy = K[0, 0], K[1, 1]
    cx, cy = K[0, 2], K[1, 2]

    X = (uu_v - cx) / fx * dd_v
    Y = (vv_v - cy) / fy * dd_v
    Z = dd_v

    points_cam = np.stack([X, Y, Z], axis=-1).astype(np.float32)

    # Sample RGB at the same pixels
    rgb_ds = rgb[::downsample, ::downsample]
    colors = rgb_ds[valid]

    return points_cam, colors


def transform_to_world(points_cam, T_c2w):
    R = T_c2w[:3, :3]
    t = T_c2w[:3, 3]
    return (R @ points_cam.T).T + t


# ---------------------------------------------------------------------------
# Frustum wireframe
# ---------------------------------------------------------------------------
def make_frustum_segments(T_c2w, K, width=1280, height=720, depth=0.15):
    """Generate line segments forming a camera frustum wireframe."""
    fx, fy = K[0, 0], K[1, 1]
    cx, cy = K[0, 2], K[1, 2]
    R = T_c2w[:3, :3]
    t = T_c2w[:3, 3]

    corners_px = np.array([[0, 0], [width, 0], [width, height], [0, height]], dtype=np.float64)
    corners_cam = []
    for u, v in corners_px:
        x = (u - cx) / fx * depth
        y = (v - cy) / fy * depth
        corners_cam.append([x, y, depth])
    corners_cam = np.array(corners_cam)

    origin_world = t.tolist()
    corners_world = ((R @ corners_cam.T).T + t).tolist()

    segments = []
    for cw in corners_world:
        segments.append([origin_world, cw])
    for i in range(4):
        segments.append([corners_world[i], corners_world[(i + 1) % 4]])
    return segments


# ---------------------------------------------------------------------------
# HTML generation (Three.js viewer)
# ---------------------------------------------------------------------------
def generate_html(cam_data, frustums, camera_poses, title, output_path):
    """Build a self-contained Three.js HTML viewer.

    cam_data: {cam_name: [[x,y,z,r,g,b], ...]}
    frustums: {cam_name: [[[x1,y1,z1],[x2,y2,z2]], ...]}
    camera_poses: {cam_name: (4,4) T_c2w}
    """
    cam_json = {}
    calib_info = {}
    for cam_name in CAM_NAMES:
        pts_list = cam_data.get(cam_name, [])
        cam_json[cam_name] = pts_list
        pos = camera_poses[cam_name][:3, 3].tolist() if cam_name in camera_poses else [0, 0, 0]
        calib_info[cam_name] = {"position": pos, "num_points": len(pts_list)}

    total_points = sum(len(v) for v in cam_json.values())

    # Centroid
    all_pts = []
    for pts_list in cam_json.values():
        for p in pts_list:
            all_pts.append(p[:3])
    if all_pts:
        centroid = np.mean(all_pts, axis=0).tolist()
    else:
        centroid = [0, 0, 0]

    # Build HTML
    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>{title}</title>
<style>
  * {{ margin:0; padding:0; box-sizing:border-box; }}
  body {{ background:#111; color:#eee; font-family:monospace; overflow:hidden; }}
  #viewer {{ width:100vw; height:100vh; }}
  #panel {{
    position:absolute; top:12px; left:12px;
    background:rgba(0,0,0,0.82); padding:14px 18px;
    border-radius:6px; font-size:13px; max-width:320px; z-index:10;
  }}
  #panel h2 {{ font-size:15px; margin-bottom:8px; }}
  #panel .row {{ margin:4px 0; display:flex; align-items:center; gap:8px; }}
  #panel .dot {{ width:10px; height:10px; border-radius:50%; display:inline-block; }}
  #panel label {{ cursor:pointer; }}
  #panel .slider-row {{ margin:8px 0; }}
  #panel .slider-row input {{ width:140px; vertical-align:middle; }}
  #panel .sep {{ border-top:1px solid #444; margin:8px 0; }}
  #panel .hint {{ font-size:11px; color:#999; }}
</style>
</head>
<body>
<div id="viewer"></div>
<div id="panel">
  <h2>{title}</h2>
  <div class="row"><b>Total points:</b>&nbsp;{total_points:,}</div>
  <div class="sep"></div>
  <div><b>Cameras</b></div>
"""

    for cam_name in CAM_NAMES:
        ci = calib_info.get(cam_name, {"num_points": 0})
        color = CAMERA_COLORS.get(cam_name, "#fff")
        html += f"""  <div class="row">
    <input type="checkbox" id="cb_{cam_name}" checked onchange="toggleCamera('{cam_name}')">
    <span class="dot" style="background:{color}"></span>
    <label for="cb_{cam_name}">{cam_name} ({ci['num_points']:,} pts)</label>
  </div>\n"""

    html += f"""
  <div class="sep"></div>
  <div><b>Color mode</b></div>
  <div class="row">
    <input type="radio" name="colorMode" value="rgb" id="cm_rgb" checked onchange="setColorMode('rgb')">
    <label for="cm_rgb">RGB</label>
    <input type="radio" name="colorMode" value="camera" id="cm_cam" onchange="setColorMode('camera')">
    <label for="cm_cam">Per-camera</label>
  </div>
  <div class="sep"></div>
  <div class="slider-row">
    <label>Point size:&nbsp;</label>
    <input type="range" id="ptSize" min="0.5" max="8" step="0.25" value="2"
           oninput="setPointSize(this.value)">
    <span id="ptSizeVal">2</span>
  </div>
  <div class="slider-row">
    <input type="checkbox" id="cb_frustum" checked onchange="toggleFrustums()">
    <label for="cb_frustum">Show frustums</label>
  </div>
  <div class="slider-row">
    <input type="checkbox" id="cb_grid" checked onchange="toggleGrid()">
    <label for="cb_grid">Show grid</label>
  </div>
  <div class="sep"></div>
  <div class="hint">Left-drag: rotate &middot; Right-drag: pan &middot; Scroll: zoom</div>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"></script>
<script>
const CAM_DATA = {json.dumps(cam_json)};
const FRUSTUMS = {json.dumps(frustums)};
const CAM_COLORS = {json.dumps(CAMERA_COLORS)};
const CENTROID = {json.dumps(centroid)};

const container = document.getElementById('viewer');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a1a);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth/window.innerHeight, 0.01, 200);
camera.position.set(CENTROID[0] + 0.8, CENTROID[1] - 0.8, CENTROID[2] - 0.5);

const renderer = new THREE.WebGLRenderer({{ antialias:true }});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(window.devicePixelRatio);
container.appendChild(renderer.domElement);

const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.target.set(CENTROID[0], CENTROID[1], CENTROID[2]);
controls.enableDamping = true;
controls.dampingFactor = 0.12;
controls.update();

const grid = new THREE.GridHelper(4, 40, 0x444444, 0x2a2a2a);
grid.position.set(CENTROID[0], CENTROID[1], CENTROID[2]);
scene.add(grid);

const axes = new THREE.AxesHelper(0.3);
axes.position.set(CENTROID[0], CENTROID[1], CENTROID[2]);
scene.add(axes);

scene.add(new THREE.AmbientLight(0xffffff, 1.0));

let colorMode = 'rgb';
const cloudObjects = {{}};

function buildCloud(camName) {{
    const data = CAM_DATA[camName];
    if (!data || data.length === 0) return null;

    const positions = new Float32Array(data.length * 3);
    const rgbColors = new Float32Array(data.length * 3);
    const camColor = new THREE.Color(CAM_COLORS[camName] || '#ffffff');

    for (let i = 0; i < data.length; i++) {{
        positions[i*3]   = data[i][0];
        positions[i*3+1] = data[i][1];
        positions[i*3+2] = data[i][2];
        rgbColors[i*3]   = data[i][3] / 255;
        rgbColors[i*3+1] = data[i][4] / 255;
        rgbColors[i*3+2] = data[i][5] / 255;
    }}

    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geom.setAttribute('color', new THREE.BufferAttribute(rgbColors, 3));
    const camColors = new Float32Array(data.length * 3);
    for (let i = 0; i < data.length; i++) {{
        camColors[i*3]   = camColor.r;
        camColors[i*3+1] = camColor.g;
        camColors[i*3+2] = camColor.b;
    }}
    geom.userData = {{ rgbColors: rgbColors, camColors: camColors }};

    const mat = new THREE.PointsMaterial({{
        size: 2, sizeAttenuation: false, vertexColors: true
    }});
    return new THREE.Points(geom, mat);
}}

for (const cam of ['wrist','ext1','ext2']) {{
    const cloud = buildCloud(cam);
    if (cloud) {{
        scene.add(cloud);
        cloudObjects[cam] = cloud;
    }}
}}

const frustumGroups = {{}};
for (const [cam, segs] of Object.entries(FRUSTUMS)) {{
    const group = new THREE.Group();
    const color = new THREE.Color(CAM_COLORS[cam] || '#ffffff');
    for (const seg of segs) {{
        const pts = [
            new THREE.Vector3(seg[0][0], seg[0][1], seg[0][2]),
            new THREE.Vector3(seg[1][0], seg[1][1], seg[1][2]),
        ];
        const lineGeom = new THREE.BufferGeometry().setFromPoints(pts);
        const line = new THREE.Line(lineGeom, new THREE.LineBasicMaterial({{ color: color, linewidth: 2 }}));
        group.add(line);
    }}
    scene.add(group);
    frustumGroups[cam] = group;
}}

function toggleCamera(cam) {{
    const cb = document.getElementById('cb_' + cam);
    if (cloudObjects[cam]) cloudObjects[cam].visible = cb.checked;
    if (frustumGroups[cam]) frustumGroups[cam].visible = cb.checked;
}}

function setColorMode(mode) {{
    colorMode = mode;
    for (const [cam, cloud] of Object.entries(cloudObjects)) {{
        const geom = cloud.geometry;
        const ud = geom.userData;
        const attr = geom.getAttribute('color');
        const src = (mode === 'camera') ? ud.camColors : ud.rgbColors;
        attr.array.set(src);
        attr.needsUpdate = true;
    }}
}}

function setPointSize(val) {{
    document.getElementById('ptSizeVal').textContent = val;
    for (const cloud of Object.values(cloudObjects)) {{
        cloud.material.size = parseFloat(val);
    }}
}}

function toggleFrustums() {{
    const on = document.getElementById('cb_frustum').checked;
    for (const g of Object.values(frustumGroups)) g.visible = on;
}}

function toggleGrid() {{
    grid.visible = document.getElementById('cb_grid').checked;
}}

function animate() {{
    requestAnimationFrame(animate);
    controls.update();
    renderer.render(scene, camera);
}}
animate();

window.addEventListener('resize', () => {{
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}});
</script>
</body>
</html>"""

    Path(output_path).parent.mkdir(parents=True, exist_ok=True)
    Path(output_path).write_text(html)
    print(f"Wrote {output_path}  ({total_points:,} points)")


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    parser = argparse.ArgumentParser(
        description="Visualize multi-camera pointcloud from step2a depth + step2b extrinsics"
    )
    parser.add_argument("--episode_dir", required=True,
                        help="Raw episode directory (has metadata, trajectory.h5, MP4s)")
    parser.add_argument("--depth_h5", required=True,
                        help="Step 2a depth H5 file")
    parser.add_argument("--cameras_json", required=True,
                        help="Step 2b cameras JSON file (ext camera extrinsics)")
    parser.add_argument("--calibration_json", required=True,
                        help="SVO calibration JSON")
    parser.add_argument("--frame_idx", type=int, default=80,
                        help="Frame index to visualize (default: 80)")
    parser.add_argument("--output_html", required=True,
                        help="Output HTML file path")
    parser.add_argument("--extrinsics_key", default="optimized_extrinsics",
                        choices=["optimized_extrinsics", "vggt_extrinsics"],
                        help="Which extrinsics to use from cameras JSON")
    parser.add_argument("--downsample", type=int, default=4,
                        help="Spatial downsample factor (default: 4)")
    parser.add_argument("--max_depth", type=float, default=3.0,
                        help="Max depth in metres (default: 3.0)")
    args = parser.parse_args()

    episode_dir = Path(args.episode_dir)

    # Load metadata
    metadata = load_episode_metadata(episode_dir)
    uuid = metadata["uuid"]
    cam_serials = {
        "wrist": metadata["wrist_cam_serial"],
        "ext1": metadata["ext1_cam_serial"],
        "ext2": metadata["ext2_cam_serial"],
    }
    episode_id = f"{metadata.get('lab', '')}+{uuid.split('+')[1] if '+' in uuid else uuid}"

    # Load calibration
    with open(args.calibration_json) as f:
        calibration_db = json.load(f)

    # Load step2b cameras JSON (ext camera extrinsics)
    with open(args.cameras_json) as f:
        cameras_json = json.load(f)

    # Load depth H5
    depth_h5 = h5py.File(args.depth_h5, "r")

    # Build per-camera pointclouds
    cam_data = {}        # cam_name -> [[x,y,z,r,g,b], ...]
    frustums = {}        # cam_name -> segments
    camera_poses = {}    # cam_name -> T_c2w (4x4)

    for cam_name in CAM_NAMES:
        serial = cam_serials[cam_name]
        print(f"Processing {cam_name} ({serial})...")

        # Intrinsics
        K = get_calibration(calibration_db, uuid, serial)

        # Depth
        if cam_name not in depth_h5:
            print(f"  Skipping {cam_name}: not in depth H5")
            continue
        depth_all = depth_h5[cam_name]["depth"]  # (T, H, W) uint16
        if args.frame_idx >= depth_all.shape[0]:
            print(f"  Skipping {cam_name}: frame_idx {args.frame_idx} >= {depth_all.shape[0]}")
            continue
        depth_m = depth_all[args.frame_idx].astype(np.float32) / 1000.0

        # RGB
        mono_mp4 = episode_dir / "recordings" / "MP4" / f"{serial}.mp4"
        stereo_mp4 = episode_dir / "recordings" / "MP4" / f"{serial}-stereo.mp4"
        mp4_path = mono_mp4 if mono_mp4.exists() else stereo_mp4
        rgb = read_frame_from_mp4(str(mp4_path), args.frame_idx)
        if rgb is None:
            print(f"  Skipping {cam_name}: cannot read MP4 frame")
            continue

        # Extrinsics (cam-to-world)
        if cam_name == "wrist":
            T_c2w = get_wrist_T_c2w(
                episode_dir / "trajectory.h5", serial, args.frame_idx
            )
        else:
            # From step2b JSON: world-to-camera -> invert to cam-to-world
            ext_key = args.extrinsics_key
            if serial not in cameras_json or ext_key not in cameras_json[serial]:
                print(f"  Skipping {cam_name}: no {ext_key} in cameras JSON")
                continue
            T_w2c = np.array(cameras_json[serial][ext_key])
            T_c2w = np.linalg.inv(T_w2c)

        camera_poses[cam_name] = T_c2w

        # Unproject depth
        points_cam, colors = unproject_depth(
            depth_m, K, rgb, max_depth=args.max_depth, downsample=args.downsample
        )
        print(f"  {len(points_cam):,} points, depth range {depth_m[depth_m > 0].min():.2f}-{depth_m.max():.2f}m")

        # Transform to world
        points_world = transform_to_world(points_cam, T_c2w)

        # Pack [x,y,z,r,g,b]
        packed = np.hstack([points_world, colors.astype(np.float32)]).tolist()
        cam_data[cam_name] = packed

        # Frustum
        frustums[cam_name] = make_frustum_segments(T_c2w, K)

    depth_h5.close()

    # Title
    title = f"{cameras_json.get('episode_id', episode_id)} frame {args.frame_idx} ({args.extrinsics_key})"

    generate_html(cam_data, frustums, camera_poses, title, args.output_html)


if __name__ == "__main__":
    main()

