#!/usr/bin/env python3
"""
Step 3b-1 visualisation:

  per-episode HTML viewer  -- 3-cam world pointcloud + 3D box wireframe overlay
  per-episode 2D collage   -- wrist RGB | RGB+mask | RGB+projected box

Reads:
  output/step3b1_singleframe_box/{ep}_box.json
  output/step2a_depth/{ep}_depth.h5
  output/step2b_extrinsics/{ep}_cameras.json
  output/step3a1_wrist_sam3_image_merged_test/{ep}_wrist_sam3_rle.json
  raw episode dir / trajectory.h5 + recordings/MP4/{serial}-stereo.mp4
"""
import argparse
import json
from pathlib import Path

import cv2
import h5py
import numpy as np
import pycocotools.mask as mask_utils
from PIL import Image
from scipy.spatial.transform import Rotation

RAW_PATH_PREFIXES = [
    "gs://xembodiment_data/r2d2/r2d2-data-full/",
    "/nfs/kun2/datasets/r2d2/r2d2-data-full/",
]
CAM_NAMES = ["wrist", "ext1", "ext2"]
CAM_COLORS = {"wrist": "#ff4444", "ext1": "#44cc44", "ext2": "#4488ff"}

# 12 edges for an 8-corner box, ordering matches step3b1_singleframe_box.py
BOX_EDGES = [
    (0, 1), (1, 2), (2, 3), (3, 0),  # top face (y > 0)
    (4, 5), (5, 6), (6, 7), (7, 4),  # bottom face
    (0, 4), (1, 5), (2, 6), (3, 7),  # verticals
]


# ---------------------------------------------------------------------------
# Helpers (re-implemented locally; the worker has identical helpers)
# ---------------------------------------------------------------------------
def resolve_episode_dir(file_path: str, raw_data_dir: str) -> Path:
    rel = file_path
    for prefix in RAW_PATH_PREFIXES:
        if rel.startswith(prefix):
            rel = rel[len(prefix):]
            break
    return Path(raw_data_dir) / Path(rel).parent


def load_episode_metadata(episode_dir: Path) -> dict:
    meta_files = list(episode_dir.glob("metadata_*.json"))
    if not meta_files:
        raise FileNotFoundError(f"No metadata in {episode_dir}")
    with open(meta_files[0]) as f:
        return json.load(f)


def load_wrist_T_c2w(trajectory_path: Path, wrist_serial: str, frame_idx: int) -> np.ndarray:
    with h5py.File(str(trajectory_path), "r") as f:
        ext = f[f"observation/camera_extrinsics/{wrist_serial}_left"][frame_idx]
    R = Rotation.from_euler("xyz", ext[3:]).as_matrix()
    T = np.eye(4, dtype=np.float64)
    T[:3, :3] = R
    T[:3, 3] = ext[:3]
    return T


def load_ext_T_c2w(cameras_json: dict, serial: str) -> np.ndarray | None:
    entry = cameras_json.get(serial)
    if not entry or "optimized_extrinsics" not in entry:
        return None
    return np.linalg.inv(np.asarray(entry["optimized_extrinsics"], dtype=np.float64))


def read_mp4_frame(mp4_path: Path, frame_idx: int) -> np.ndarray | None:
    cap = cv2.VideoCapture(str(mp4_path))
    if not cap.isOpened():
        return None
    w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
    is_stereo = w > 1920
    cap.set(cv2.CAP_PROP_POS_FRAMES, frame_idx)
    ret, frame = cap.read()
    cap.release()
    if not ret:
        return None
    rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
    if is_stereo:
        rgb = rgb[:, : w // 2]
    return rgb


def unproject_depth(depth_m: np.ndarray, K: np.ndarray, downsample: int, max_depth: float):
    H, W = depth_m.shape
    u = np.arange(0, W, downsample)
    v = np.arange(0, H, downsample)
    uu, vv = np.meshgrid(u, v)
    dd = depth_m[::downsample, ::downsample]
    valid = (dd > 0.01) & (dd < max_depth) & np.isfinite(dd)
    fx, fy = K[0, 0], K[1, 1]
    cx, cy = K[0, 2], K[1, 2]
    z = dd[valid].astype(np.float32)
    x = (uu[valid].astype(np.float32) - cx) / fx * z
    y = (vv[valid].astype(np.float32) - cy) / fy * z
    return np.stack([x, y, z], axis=-1), valid


def transform_to_world(pts_cam: np.ndarray, T_c2w: np.ndarray) -> np.ndarray:
    return (T_c2w[:3, :3] @ pts_cam.T).T + T_c2w[:3, 3]


# ---------------------------------------------------------------------------
# 3D pointcloud collection
# ---------------------------------------------------------------------------
def collect_world_pointcloud(
    depth_h5: Path,
    cameras_json: dict,
    metadata: dict,
    trajectory_path: Path,
    frame_idx: int,
    episode_dir: Path,
    downsample: int,
    max_depth: float,
):
    """Return {cam: [[x,y,z,r,g,b], ...]} + camera_poses."""
    cam_data = {}
    cam_poses = {}
    serials = {
        "wrist": metadata["wrist_cam_serial"],
        "ext1": metadata["ext1_cam_serial"],
        "ext2": metadata["ext2_cam_serial"],
    }
    with h5py.File(str(depth_h5), "r") as f:
        for cam in CAM_NAMES:
            if cam not in f:
                continue
            depth_ds = f[cam]["depth"]
            if frame_idx >= depth_ds.shape[0]:
                continue
            depth_m = depth_ds[frame_idx].astype(np.float32) / 1000.0
            K = np.asarray(f[cam]["intrinsic"][:], dtype=np.float64)
            serial = serials[cam]

            # RGB
            mono_mp4 = episode_dir / "recordings" / "MP4" / f"{serial}.mp4"
            stereo_mp4 = episode_dir / "recordings" / "MP4" / f"{serial}-stereo.mp4"
            mp4 = mono_mp4 if mono_mp4.exists() else stereo_mp4
            rgb = read_mp4_frame(mp4, frame_idx)
            if rgb is None:
                continue
            if rgb.shape[:2] != depth_m.shape:
                rgb = cv2.resize(rgb, (depth_m.shape[1], depth_m.shape[0]))

            # Pose
            if cam == "wrist":
                T_c2w = load_wrist_T_c2w(trajectory_path, serial, frame_idx)
            else:
                T_c2w = load_ext_T_c2w(cameras_json, serial)
                if T_c2w is None:
                    continue
            cam_poses[cam] = T_c2w

            pts_cam, valid_mask = unproject_depth(depth_m, K, downsample, max_depth)
            pts_world = transform_to_world(pts_cam, T_c2w)
            colors = rgb[::downsample, ::downsample][valid_mask]
            packed = np.hstack([pts_world, colors.astype(np.float32)]).tolist()
            cam_data[cam] = packed
    return cam_data, cam_poses


# ---------------------------------------------------------------------------
# HTML
# ---------------------------------------------------------------------------
def make_box_segments(corners: list[list[float]]) -> list[list[list[float]]]:
    return [[corners[i], corners[j]] for i, j in BOX_EDGES]


def generate_html(cam_data, cam_poses, box_segments_world, box_label, output_path: Path, title: str):
    cam_json = {c: cam_data.get(c, []) for c in CAM_NAMES}
    total = sum(len(v) for v in cam_json.values())

    # Centroid (skip empty)
    all_pts = [p[:3] for v in cam_json.values() for p in v]
    centroid = (np.mean(all_pts, axis=0).tolist() if all_pts else [0, 0, 0])

    html = f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>{title}</title>
