"""
    for cam in CAM_NAMES:
        n = len(cam_json[cam])
        c = CAM_COLORS[cam]
        html += (f'<div class="row"><input type="checkbox" id="cb_{cam}" checked '
                 f'onchange="toggleCam(\'{cam}\')"><span class="dot" '
