  boxGroup.add(new THREE.Line(lg,lm));
}}
scene.add(boxGroup);
function toggleCam(c){{ if(clouds[c]) clouds[c].visible=document.getElementById('cb_'+c).checked; }}
function toggleBox(){{ boxGroup.visible=document.getElementById('cb_box').checked; }}
