def _apply_axis_swap(corners: np.ndarray, swap: str) -> np.ndarray:
    """Permute corner coordinates IN-PLACE around the box center.

    swap ∈ {'none', 'xz', 'xy', 'yz'}: swap the named pair of coords of each
    corner's OFFSET from the box center, then re-add the center. This
    preserves the box center location while re-orienting the box axes.
    """
    if swap == "none" or swap is None:
        return corners
    center = corners.mean(axis=0)
    offsets = corners - center
    if swap == "xz":
        offsets[:, [0, 2]] = offsets[:, [2, 0]]
    elif swap == "xy":
        offsets[:, [0, 1]] = offsets[:, [1, 0]]
    elif swap == "yz":
        offsets[:, [1, 2]] = offsets[:, [2, 1]]
    else:
        raise ValueError(f"Unknown swap mode: {swap}")
    return offsets + center

