for res, group_eids in (buckets.items() if args.batch_size > 1 else [(None, eids)]):
    if not group_eids:
        continue
    if args.batch_size > 1:
        log(f"Processing bucket {res[0]}x{res[1]}: {len(group_eids)} episodes")
    i = 0
    while i < len(group_eids):
        chunk = group_eids[i : i + args.batch_size]
        i += args.batch_size

    # Phase 1: prepare each episode (CPU). Drop ones that error out before GPU.
    preps = []
    for eid in chunk:
        vlm_result = vlm_by_eid.get(eid)
        if vlm_result is None:
            record(eid, "no_vlm_result")
            continue
        try:
            prep = prepare_episode(
                vlm_result=vlm_result,
                step3a1_dir=step3a1_dir,
                step2a_dir=step2a_dir,
                step2b_dir=step2b_dir,
                raw_data_dir=args.raw_data_dir,
                output_dir=output_dir,
                max_depth=args.max_depth,
                ext_extrinsics_source=args.ext_extrinsics_source,
            )
        except Exception as e:
            record(eid, f"prepare_error: {e}")
            continue
        if isinstance(prep, str):
            record(eid, prep)
            continue
        preps.append(prep)

    if not preps:
        continue

    # Phase 2: SAM3D (GPU). One forward batch over all prepared episodes.
    try:
        if batched_runner is None or len(preps) == 1:
            output, elapsed = run_one_sam3d(sam3d_model, preps[0], args.device, args.seed)
            outputs = [output]
            elapseds = [elapsed]
        else:
            outputs, batch_elapsed = run_batch_sam3d(batched_runner, preps, args.device, args.seed)
            # Attribute elapsed time per-sample as batch_elapsed / N.
            elapseds = [batch_elapsed / len(preps)] * len(preps)
            log(f"  batch[{len(preps)}] sam3d elapsed: {batch_elapsed:.1f}s "
                f"({batch_elapsed/len(preps):.1f}s/ep)")
    except Exception as e:
        tb = traceback.format_exc()
        log(f"  sam3d_error full traceback:\n{tb}")
        for prep in preps:
            record(prep["episode_id"], f"sam3d_error: {e}")
        continue

    # Phase 3: per-sample finalize (decompose + write).
    for prep, output, elapsed in zip(preps, outputs, elapseds):
        try:
            status = finalize_episode(
                prep, output, elapsed, output_dir,
                args.save_glb, args.device,
            )
        except Exception as e:
            status = f"finalize_error: {e}\n{traceback.format_exc()}"
        record(prep["episode_id"], status)

    gc.collect()
    torch.cuda.empty_cache()

